Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

int main() {
    long long x, y, n;
    scanf("%lld %lld %lld", &x, &y, &n);
    long long sn = 10000000, sd = 1;
    for (int den = 1; den <= n; ++den) {
        // compute floor and ceil numerators
        long long floor_num = x * den / y;
        long long ceil_num = floor_num + 1;
        long long num;
        // choose the one with smaller absolute difference
        long long diff_floor = llabs(x * den - floor_num * y);
        long long diff_ceil = llabs(x * den - ceil_num * y);
        if (diff_floor <= diff_ceil) num = floor_num;
        else num = ceil_num;
        // update if better
        if (llabs(x * sd - sn * y) * den > llabs(x * den - num * y) * sd) {
            sn = num;
            sd = den;
        }
    }
    printf("%lld/%lld\n", sn, sd);
    return 0;
}
